async function insertHtmlStructure(){const n=document.getElementById("container-234-parent");if(!n){console.error("Container not found.");return}n.style.height="";const t=document.getElementById("id-argomento");if(!t||!t.hasAttribute("data-model")){console.error("Data model element or attribute not found.");return}const i=t.getAttribute("data-model");let r=await fetchAndProcessData(i);if(!(r.Contenuti<1)){const u=popolaHTML(r.Contenuti,i);n.appendChild(u);resizeView()}}async function fetchAndProcessData(n){try{const t=await grab9More(n);return console.log("Dati ottenuti:",t),t}catch(t){return console.error("Errore durante la richiesta:",t),[]}}function popolaHTML(n,t){const i=document.createElement("div");i.className="row container-class234 children-div-all second-lv-conteiner";for(let r=0;r<n.length;r++){const e=document.createElement("div");e.className="item-argument";e.setAttribute("data-index",r);const u=document.createElement("form");u.action="/Argument/Article";u.method="post";u.className="w-100 h-100";const o=document.createElement("input");o.type="hidden";o.name="id_articolo";o.value=n[r].Title;const s=document.createElement("input");s.type="hidden";s.name="id_argomento";s.value=t;const f=document.createElement("button");f.type="submit";f.className="invisible-button";const h=document.createElement("img");h.src=n[r].ImgPath;h.alt="Immagine";const c=document.createElement("span");c.classList.add("colore-scritte-LV");c.textContent=n[r].Title;f.appendChild(h);f.appendChild(c);u.appendChild(o);u.appendChild(s);u.appendChild(f);e.appendChild(u);i.appendChild(e)}return i}